export function handleRequest(request: { temperature: number; unitFrom: 'Celsius' | 'Fahrenheit'; unitTo: 'Celsius' | 'Fahrenheit' }): { convertedTemperature: number; unit: 'Celsius' | 'Fahrenheit' } {
  try {
    const temperature = request.temperature;
    const unitFrom = request.unitFrom;
    const unitTo = request.unitTo;

    let convertedTemperature: number;
    if (unitFrom === 'Celsius') {
      if (unitTo === 'Fahrenheit') {
        convertedTemperature = (temperature * 9 / 5) + 32;
      } else if (unitTo === 'Celsius') {
        convertedTemperature = temperature;
      } else {
        throw new Error('Invalid unitTo');
      }
    } else if (unitFrom === 'Fahrenheit') {
      if (unitTo === 'Celsius') {
        convertedTemperature = (temperature - 32) * 5 / 9;
      } else if (unitTo === 'Fahrenheit') {
        convertedTemperature = temperature;
      } else {
        throw new Error('Invalid unitTo');
      }
    } else {
      throw new Error('Invalid unitFrom');
    }

    return { convertedTemperature, unit: unitTo };
  } catch (error) {
    console.error(error);
    return { convertedTemperature: 0, unit: 'Celsius' };
  }
}

export function render(container: HTMLElement) {
  const title = document.createElement('h1');
  title.textContent = 'Temperature Converter';
  container.appendChild(title);
  const desc = document.createElement('p');
  desc.textContent = 'Convert temperatures between Celsius and Fahrenheit';
  container.appendChild(desc);
  const inputRow = document.createElement('div');
  inputRow.className = 'input-row';
  const inputGroup = document.createElement('div');
  inputGroup.className = 'input-group';
  const inputLabel = document.createElement('label');
  inputLabel.htmlFor = 'inputValue';
  inputLabel.textContent = 'Value';
  inputGroup.appendChild(inputLabel);
  const inputField = document.createElement('input');
  inputField.id = 'inputValue';
  inputField.type = 'number';
  inputField.placeholder = 'Enter value';
  inputGroup.appendChild(inputField);
  inputRow.appendChild(inputGroup);
  const unitGroup = document.createElement('div');
  unitGroup.className = 'unit-group';
  const fromLabel = document.createElement('label');
  fromLabel.htmlFor = 'fromUnit';
  fromLabel.textContent = 'From';
  unitGroup.appendChild(fromLabel);
  const fromSelect = document.createElement('select');
  fromSelect.id = 'fromUnit';
  fromSelect.className = 'form-control';
  const options = ['Celsius', 'Fahrenheit'];
  options.forEach((unit) => {
    const option = document.createElement('option');
    option.value = unit;
    option.textContent = unit;
    fromSelect.appendChild(option);
  });
  fromSelect.value = 'Celsius';
  unitGroup.appendChild(fromSelect);
  const toLabel = document.createElement('label');
  toLabel.htmlFor = 'toUnit';
  toLabel.textContent = 'To';
  unitGroup.appendChild(toLabel);
  const toSelect = document.createElement('select');
  toSelect.id = 'toUnit';
  toSelect.className = 'form-control';
  options.forEach((unit) => {
    const option = document.createElement('option');
    option.value = unit;
    option.textContent = unit;
    toSelect.appendChild(option);
  });
  toSelect.value = 'Fahrenheit';
  unitGroup.appendChild(toSelect);
  inputRow.appendChild(unitGroup);
  container.appendChild(inputRow);
  const resultDisplay = document.createElement('div');
  resultDisplay.id = 'resultDisplay';
  resultDisplay.className = 'result';
  container.appendChild(resultDisplay);
  const convertBtn = document.createElement('button');
  convertBtn.className = 'btn';
  convertBtn.textContent = 'Convert';
  convertBtn.onclick = () => {
    const value = parseFloat(document.getElementById('inputValue')!.value);
    if (isNaN(value)) {
      resultDisplay.textContent = 'Invalid input';
      return;
    }
    const fromUnit = (document.getElementById('fromUnit') as HTMLSelectElement).value;
    const toUnit = (document.getElementById('toUnit') as HTMLSelectElement).value;
    const result = handleRequest({ temperature: value, unitFrom: fromUnit, unitTo: toUnit });
    resultDisplay.textContent = `${value} ${fromUnit} = ${result.convertedTemperature.toFixed(2)} ${result.unit}`;
  };
  container.appendChild(convertBtn);
  const resetBtn = document.createElement('button');
  resetBtn.className = 'btn';
  resetBtn.textContent = 'Reset';
  resetBtn.onclick = () => {
    document.getElementById('inputValue')!.value = '';
    resultDisplay.textContent = '';
  };
  container.appendChild(resetBtn);
}

