import { handleRequest } from '../input-handler/input-handler.ts';

export function convertTemperature(temperature: number, fromUnit: 'Celsius' | 'Fahrenheit', toUnit: 'Celsius' | 'Fahrenheit'): number {
  if (fromUnit === 'Celsius' && toUnit === 'Fahrenheit') {
    return (temperature * 9 / 5) + 32;
  } else if (fromUnit === 'Fahrenheit' && toUnit === 'Celsius') {
    return (temperature - 32) * 5 / 9;
  }
  return temperature;
}

export function getConversionResult(temperature: number, fromUnit: 'Celsius' | 'Fahrenheit', toUnit: 'Celsius' | 'Fahrenheit'): { converted: number; toUnit: 'Celsius' | 'Fahrenheit' } {
  const converted = convertTemperature(temperature, fromUnit, toUnit);
  return { converted, toUnit };
}
